def metric_help(name, help_text):
    return ' '.join(['# HELP', name, help_text])


def metric_type(name, type_str):
    return ' '.join(['# TYPE', name, type_str])


def metric_value(name, value):
    return ' '.join([name, str(value)])


def metric_labeled(name, labels, value):
    return ''.join([name, '{', labels, '} ', str(value)])


def label_pair(key, value):
    return ''.join([key, '="', str(value), '"'])


def labels_list(l1, l2, l3):
    return ','.join([l1, l2, l3])


def metric_timestamp(metric_str, ts):
    return ' '.join([metric_str, str(ts)])


def metric_comment(text):
    return ' '.join(['#', text])


def request_labels(method, path, status):
    return labels_list(
        label_pair('method', method),
        label_pair('path', path),
        label_pair('status', status),
    )


def family_header(name, help_text, type_str):
    return '\n'.join([metric_help(name, help_text), metric_type(name, type_str)])


def request_sample(name, method, path, status, value, ts):
    labeled = metric_labeled(name, request_labels(method, path, status), value)
    return metric_timestamp(labeled, ts)


def main():
    ts = 1700000000000
    requests = [
        ('GET', '/api/users', 200, 1024),
        ('POST', '/api/users', 201, 57),
        ('GET', '/healthz', 503, 3),
    ]
    print(metric_comment(' '.join(['scrape timestamp (ms):', str(ts)])))
    print(family_header(
        'http_requests_total',
        'Total number of HTTP requests.',
        'counter',
    ))
    for method, path, status, count in requests:
        print(request_sample('http_requests_total', method, path, status, count, ts))
    print(family_header(
        'process_start_time_seconds',
        'Start time of the process since unix epoch.',
        'gauge',
    ))
    print(metric_value('process_start_time_seconds', 1699999000.5))
    print(metric_comment(' '.join(['samples exported:', str(len(requests) + 1)])))


if __name__ == '__main__':
    main()

