def _octet(value, limit=255):
    number = int(value)
    if not 0 <= number <= limit:
        raise ValueError("value %d out of range 0..%d" % (number, limit))
    return number


def _hex_byte(value):
    return "%02x" % _octet(value)


def mac_colon(b1, b2, b3, b4, b5, b6):
    return _hex_byte(b1) + ":" + _hex_byte(b2) + ":" + _hex_byte(b3) + ":" + \
                     _hex_byte(b4) + ":" + _hex_byte(b5) + ":" + _hex_byte(b6)


def mac_dash(b1, b2, b3, b4, b5, b6):
    return _hex_byte(b1) + "-" + _hex_byte(b2) + "-" + _hex_byte(b3) + "-" + \
                     _hex_byte(b4) + "-" + _hex_byte(b5) + "-" + _hex_byte(b6)


def ipv4_str(o1, o2, o3, o4):
    return str(_octet(o1)) + "." + str(_octet(o2)) + "." + \
                     str(_octet(o3)) + "." + str(_octet(o4))


def ipv6_subnet(prefix, cidr):
    return prefix + "/" + str(_octet(cidr, 128))


def socket_addr(ip, port):
    return ip + ":" + str(_octet(port, 65535))


def url_host(proto, ip, port):
    return proto + "://" + ip + ":" + str(_octet(port, 65535))


def ipsec_spi(src, dst, spi):
    return src + "-" + dst + "-" + spi


def asn_str(asn_prefix, num):
    return asn_prefix + ":" + str(num)


def labelled(label, value):
    return label + ": " + value


def interface_line(name, mac_bytes, octets, port):
    address = ipv4_str(*octets)
    details = mac_colon(*mac_bytes) + ", " + mac_dash(*mac_bytes) + ", " + \
                         socket_addr(address, port) + ", " + \
                         url_host("https", address, port)
    return labelled(name, details)


def main():
    interfaces = [
        ("eth0", (0x00, 0x1B, 0x44, 0x11, 0x3A, 0xB7), (192, 168, 1, 10), 443),
        ("eth1", (0xDE, 0xAD, 0xBE, 0xEF, 0x00, 0x01), (10, 0, 0, 254), 8443),
    ]
    for name, mac_bytes, octets, port in interfaces:
        print(interface_line(name, mac_bytes, octets, port))

    lan = ipv4_str(192, 168, 1, 10)
    wan = ipv4_str(10, 0, 0, 254)
    print(labelled("tunnel", ipsec_spi(lan, wan, "0x1a2b3c4d")))
    print(labelled("subnet", ipv6_subnet("2001:db8:abcd::", 48)))
    print(labelled("link-local", ipv6_subnet("fd00::", 8)))
    print(labelled("community", asn_str("65001", 100)))


if __name__ == "__main__":
    main()

