def scale_filter(w, h):
    """Return the scale parameters 'w:h'."""
    return ':'.join([str(w), str(h)])


def crop_filter(w, h, x, y):
    """Return the crop parameters 'w:h:x:y'."""
    return ':'.join([str(w), str(h), str(x), str(y)])


def pad_filter(w, h, x, y, color):
    """Return the pad parameters 'w:h:x:y:color'."""
    return ':'.join([str(w), str(h), str(x), str(y), str(color)])


def fps_filter(fps):
    """Return 'fps=<value>'."""
    return '='.join(['fps', str(fps)])


def drawtext_filter(font, text, x, y):
    """Return the drawtext parameter list without separators."""
    return ''.join(['fontfile=', font, ':text=', text, ':x=', str(x), ':y=', str(y)])


def overlay_filter(x, y):
    """Return 'overlay=<x>:<y>'."""
    return ''.join(['overlay=', str(x), ':', str(y)])


