INVALID_CHARS = set('+#/ ')
SEVERITIES = ('info', 'warning', 'critical')


def _validate(label, value):
    if not value:
        raise ValueError(''.join([label, ' must not be empty']))
    for char in value:
        if char in INVALID_CHARS:
            raise ValueError(''.join([label, ' contains an illegal character: ', char]))
    return value


def _device_prefix(tenant, device_id):
    _validate('tenant', tenant)
    _validate('device_id', device_id)
    return '/'.join([tenant, device_id])


def get_telemetry_topic(tenant, device_id):
    return '/'.join([_device_prefix(tenant, device_id), 'telemetry'])


def get_command_topic(tenant, device_id, command_name):
    _validate('command_name', command_name)
    return '/'.join([_device_prefix(tenant, device_id), 'commands', command_name])


def get_status_topic(tenant, device_id):
    return '/'.join([_device_prefix(tenant, device_id), 'status'])


def get_alert_topic(tenant, device_id, severity):
    _validate('severity', severity)
    level = severity.lower()
    if level not in SEVERITIES:
        raise ValueError(''.join(['unknown severity: ', severity]))
    return '/'.join([_device_prefix(tenant, device_id), 'alerts', level])


def get_wildcard_topic(tenant, device_id):
    return '/'.join([_device_prefix(tenant, device_id), '#'])


def build_topic_set(tenant, device_id, commands=(), severities=()):
    topics = {
        'telemetry': get_telemetry_topic(tenant, device_id),
        'status': get_status_topic(tenant, device_id),
        'wildcard': get_wildcard_topic(tenant, device_id),
    }
    for command in commands:
        key = ''.join(['command:', command])
        topics[key] = get_command_topic(tenant, device_id, command)
    for severity in severities:
        key = ':'.join(['alert', severity.lower()])
        topics[key] = get_alert_topic(tenant, device_id, severity)
    return topics


def format_topic_lines(topics):
    width = max(len(key) for key in topics)
    lines = []
    for key in sorted(topics):
        lines.append(''.join([key.ljust(width), '  ->  ', topics[key]]))
    return lines


def main():
    tenant, device_id = 'tenant1', 'device2'
    topics = build_topic_set(tenant, device_id, ('reboot', 'set-interval'), ('info', 'CRITICAL'))
    print(''.join(['Topics for ', tenant, '/', device_id, ':']))
    for line in format_topic_lines(topics):
        print(line)
    subscriptions = ', '.join([topics['wildcard'], topics['status']])
    print(''.join(['Subscriptions: ', subscriptions]))
    try:
        get_alert_topic(tenant, device_id, 'fatal')
    except ValueError as exc:
        print(': '.join(['rejected', str(exc)]))


if __name__ == '__main__':
    main()

