JMX_SPECIAL = set(':,="*?')


def _quote(value):
    """Quote an ObjectName property value if it contains reserved characters."""
    if not any(ch in JMX_SPECIAL for ch in value):
        return value
    escaped = ''
    for ch in value:
        if ch in '"*?\\':
            escaped += '\\'
        escaped += ch
    return ''.join(['"', escaped, '"'])


def _pair(key, value):
    """Render a single key=value property of an ObjectName."""
    if not key:
        raise ValueError('property key must not be empty')
    return '='.join([key, _quote(value)])


def _object_name(domain, properties):
    """Combine a validated domain, the colon separator and the property list."""
    if not domain:
        raise ValueError('domain must not be empty')
    for ch in domain:
        if ch in JMX_SPECIAL:
            raise ValueError(''.join(['illegal character ', ch, ' in domain ', domain]))
    return ''.join([domain, ':', properties])


def build_memory_mbean(pool_name):
    if pool_name is None:
        return _object_name('java.lang', _pair('type', 'Memory'))
    properties = ','.join([_pair('type', 'MemoryPool'), _pair('name', pool_name)])
    return _object_name('java.lang', properties)


