    if not key or not key.strip():
        raise ValueError("mapping key must be a non-empty string")
    return key.strip()


def _normalize_command(command):
    command = (command or "").strip()
    if not command:
        raise ValueError("mapping command must be a non-empty string")
    if command.startswith(":") and not command.endswith("<CR>"):
        command = ''.join([command, "<CR>"])
    return command


def _build_map(mode, key, command):
    return ' '.join([mode, _normalize_key(key), _normalize_command(command)])


def build_normal_map(key, command):
    return _build_map("nnoremap", key, command)


def build_insert_map(key, command):
    return _build_map("inoremap", key, command)


def build_visual_map(key, command):
    return _build_map("vnoremap", key, command)


def build_leader_map(key, command):
    key = _normalize_key(key)
    trigger = key if key.startswith("<leader>") else ''.join(["<leader>", key])
    return _build_map("nnoremap", trigger, command)


def build_plugin_map(plugin, command):
    plugin = _normalize_key(plugin)
    trigger = plugin if plugin.startswith("<Plug>") else ''.join(["<Plug>", plugin])
    return _build_map("nmap", trigger, command)


