def _fmt(value):
    text = ("%.4f" % float(value)).rstrip('0').rstrip('.')
    return text if text not in ('', '-0') else '0'


def _word(letter, value):
    return ''.join([letter, _fmt(value)])


def _comment(text):
    return ''.join(['(', text, ')'])


def _command(code, axes):
    terms = [code]
    for letter, value in axes:
        if value is not None:
            terms.append(_word(letter, value))
    return ' '.join(terms)


def linear_move(x=None, y=None, z=None, f=None):
    return _command('G1', [('X', x), ('Y', y), ('Z', z), ('F', f)])


def rapid_move(x=None, y=None, z=None):
    return _command('G0', [('X', x), ('Y', y), ('Z', z)])


def set_spindle_speed(s):
    if s < 0:
        raise ValueError(''.join(['negative spindle speed: ', _fmt(s)]))
    return _command('M3', [('S', s)])


def tool_change(t):
    if int(t) != t or t < 1:
        raise ValueError(''.join(['invalid tool number: ', repr(t)]))
    return ' '.join([_word('T', t), 'M6'])


def dwell(p):
    if p < 0:
        raise ValueError(''.join(['negative dwell time: ', _fmt(p)]))
    return _command('G4', [('P', p)])


def square_path(size, depth, feed):
    corners = [(size, 0.0), (size, size), (0.0, size), (0.0, 0.0)]
    moves = [linear_move(z=depth, f=feed / 2.0)]
    for cx, cy in corners:
        moves.append(linear_move(x=cx, y=cy, f=feed))
    return moves


def program_header(name, tool, feed):
    facts = [name, _word('T', tool), _word('F', feed)]
    return _comment(', '.join(facts))


