    lines.append(rapid_move(z=5.0))
    lines.append(rapid_move(x=0.0, y=0.0))
    lines.extend(square_path(size, depth, feed))
    lines.append(rapid_move(z=25.0))
    lines.append('M5')
    lines.append('M30')
    return lines


