ZK_SERVICES = "services"
ZK_ELECTION = "election"
ZK_CONFIG = "config"
ZK_LOCKS = "locks"
ZK_WORKERS = "workers"

_ILLEGAL = set("/\0 \t\n")


def _clean(label, value):
    if not isinstance(value, str) or not value:
        raise ValueError(''.join([label, " must be a non-empty string"]))
    for ch in value:
        if ch in _ILLEGAL:
            raise ValueError(''.join([label, " contains illegal character ", repr(ch)]))
    if value in (".", ".."):
        raise ValueError(''.join([label, " may not be '.' or '..'"]))
    return value


def build_service_registration_path(service_name, instance_id):
    return '/'.join(["", ZK_SERVICES,
                     _clean("service_name", service_name),
                     _clean("instance_id", instance_id)])


def build_leader_election_path(cluster_name):
    return '/'.join(["", ZK_ELECTION,
                     _clean("cluster_name", cluster_name),
                     "leader"])


def build_config_path(app_name, env):
    return '/'.join(["", ZK_CONFIG,
                     _clean("app_name", app_name),
                     _clean("env", env).lower()])


def build_lock_path(resource_name):
    return '/'.join(["", ZK_LOCKS, _clean("resource_name", resource_name)])


def build_worker_task_path(worker_id, task_id):
    return '/'.join(["", ZK_WORKERS,
                     _clean("worker_id", worker_id),
                     "tasks",
                     _clean("task_id", task_id)])


def path_components(path):
    return [component for component in path.split("/") if component]


def parent_path(path):
    head = path.rsplit("/", 1)[0]
    return head or "/"


def describe_path(path):
    depth = len(path_components(path))
    return ''.join([path, " (depth ", str(depth), ")"])


