from urllib.parse import quote

_MECARD_SPECIALS = '\\:;,"'
_WIFI_SPECIALS = '\\:;,"'


def _escape(value, specials):
    """Backslash-escape the characters that would otherwise end a field."""
    escaped = ''
    for ch in value:
        if ch in specials:
            escaped += '\\'
        escaped += ch
    return escaped


def vcard_name_line(last, first, middle):
    """The vCard N property: family;given;additional;prefix;suffix."""
    components = ';'.join([last, first, middle, '', ''])
    return ''.join(['N:', components])


def mecard_payload(name, phone, email):
    name_field = ':'.join(['N', _escape(name, _MECARD_SPECIALS)])
    tel_field = ':'.join(['TEL', _escape(phone, _MECARD_SPECIALS)])
    mail_field = ':'.join(['EMAIL', _escape(email, _MECARD_SPECIALS)])
    body = ';'.join([name_field, tel_field, mail_field])
    return ''.join(['MECARD:', body, ';;'])


def wifi_payload(ssid, password, enc_type, hidden):
    ssid_field = ':'.join(['S', _escape(ssid, _WIFI_SPECIALS)])
    type_field = ':'.join(['T', enc_type])
    pass_field = ':'.join(['P', _escape(password, _WIFI_SPECIALS)])
    hidden_field = ':'.join(['H', hidden])
    body = ';'.join([ssid_field, type_field, pass_field, hidden_field])
    return ''.join(['WIFI:', body, ';;'])


def sms_payload(phone, body):
    return ':'.join(['smsto', phone, body])


def mailto_payload(email, sub, body):
    subject_pair = '='.join(['subject', quote(sub)])
    body_pair = '='.join(['body', quote(body)])
    query = '&'.join([subject_pair, body_pair])
    return ''.join(['mailto:', email, '?', query])


def geo_payload(lat, lon, alt):
    coords = ','.join([lat, lon, alt])
    return ''.join(['geo:', coords])


def event_payload(title, start, end, loc):
    return '\r\n'.join([
        'BEGIN:VEVENT',
        ':'.join(['SUMMARY', title]),
        ':'.join(['DTSTART', start]),
        ':'.join(['DTEND', end]),
        ':'.join(['LOCATION', loc]),
        'END:VEVENT',
    ])


def phone_payload(number):
    digits = ''
    for ch in number:
        if ch.isdigit() or ch == '+':
            digits += ch
    return ''.join(['tel:', digits])


def main():
    entries = [
        ('vcard-name', vcard_name_line('Doe', 'John', 'Q')),
        ('mecard', mecard_payload('Doe,John', '+15550101', 'john@example.com')),
        ('wifi', wifi_payload('MyNet', 'pass', 'WPA', 'false')),
        ('sms', sms_payload('+15550101', 'Call me back')),
        ('mailto', mailto_payload('john@example.com', 'Hi', 'See attached')),
        ('geo', geo_payload('40.7', '-74.0', '10')),
        ('event', event_payload('Standup', '20260918T090000Z', '20260918T091500Z', 'Room 2')),
        ('tel', phone_payload('(555) 010-1234')),
    ]
    for label, payload in entries:
        print(''.join([label, ': ', payload]))


if __name__ == '__main__':
    main()

def _style(fg, bg):
    """Return a tmux style directive such as '#[fg=green,bg=default]'."""
    return ''.join(['#[fg=', fg, ',bg=', bg, ']'])


def _require(field, value):
    """Reject empty components, which would silently collapse a segment."""
    if not value:
        raise ValueError(''.join(['empty status field: ', field]))


def session_info(name, windows):
    _require('name', name)
    _require('windows', windows)
    return ''.join(['[', name, '] ', windows, ' windows'])


def active_window(index, name, flags):
    _require('index', index)
    _require('name', name)
    body = ''.join([index, ':', name, flags])
    return ''.join([_style('black', 'green'), body, _style('default', 'default')])


def inactive_window(index, name):
    _require('index', index)
    _require('name', name)
    return ''.join([index, ':', name])


def battery_status(pct, state):
    _require('pct', pct)
    _require('state', state)
    percent = ''.join([pct, '%'])
    state_text = ''.join(['(', state, ')'])
    return ' '.join(['BAT', percent, state_text])


def cpu_load(avg1, avg5, avg15):
    _require('avg1', avg1)
    _require('avg5', avg5)
    _require('avg15', avg15)
    averages = ' '.join([avg1, avg5, avg15])
    return ''.join(['CPU: ', averages])


def memory_usage(used, total):
    _require('used', used)
    _require('total', total)
    ratio = '/'.join([used, total])
    return ' '.join(['MEM', ratio])


def network_speed(rx, tx):
    _require('rx', rx)
    _require('tx', tx)
    down = ''.join(['v', rx])
    up = ''.join(['^', tx])
    return ' '.join([down, up])


def clock_display(date, time, tz):
    _require('date', date)
    _require('time', time)
    _require('tz', tz)
    return ' '.join([date, time, tz])


def main():
    windows = ' '.join([active_window('1', 'editor', '*'),
                        inactive_window('2', 'shell'),
                        inactive_window('3', 'logs')])
    status = ' | '.join([session_info('work', '3'),
                         windows,
                         cpu_load('1.5', '2.0', '1.8'),
                         memory_usage('3.2G', '8G'),
                         network_speed('120K', '18K'),
                         battery_status('87', 'charging'),
                         clock_display('2023-01-01', '12:00', 'UTC')])
    print(status)


