def rule_header(name, tag1, tag2):
    tags = tag1 + ' ' + tag2
    return 'rule ' + name + ' : ' + tags + ' {'


def meta_author(name, date):
    return 'author = "' + name + '", date = "' + date + '"'


def meta_desc(desc, version):
    return 'description = "' + desc + '", version = "' + version + '"'


def string_hex(var_name, hex_bytes):
    cleaned = _normalize(hex_bytes).upper()
    return var_name + ' = { ' + cleaned + ' }'


def string_text(var_name, text, modifiers):
    mods = _normalize(modifiers)
    if mods:
        return var_name + ' = "' + text + '" ' + mods
    return var_name + ' = "' + text + '"'


def condition_all_of(var1, var2, var3):
    variables = var1 + ', ' + var2 + ', ' + var3
    return 'all of (' + variables + ')'


def condition_filesize(min_kb, max_kb):
    return 'filesize >' + ' ' + min_kb + 'KB' + ' ' + 'and' + ' ' + 'filesize <' + ' ' + max_kb + 'KB'


def condition_pe_section(sec_name, sec_size):
    name_test = 'pe.sections[0].name == "' + sec_name + '"'
    return name_test + ' ' + 'and' + ' ' + 'pe.sections[0].raw_data_size ==' + ' ' + sec_size


def _block(title, lines):
    text = '    ' + title + ':'
    for line in lines:
        text = text + '\n        ' + line
    return text


def _condition_block(lines):
    text = '    condition:'
    keyword = ''
    for line in lines:
        text = text + '\n        ' + keyword + line
        keyword = 'and '
    return text


def build_rule(header, meta_lines, string_lines, condition_lines):
    meta_block = _block('meta', meta_lines)
    strings_block = _block('strings', string_lines)
    condition_block = _condition_block(condition_lines)
    return header + '\n' + meta_block + '\n' + strings_block + '\n' + condition_block + '\n' + '}'


def main():
    header = rule_header('Suspicious_Dropper', 'malware', 'dropper')
    meta_lines = [
        meta_author('A. Analyst', '2026-09-18'),
        meta_desc('Detects a small PE dropper family', '1.2'),
    ]
    string_lines = [
        string_hex('$hex1', '4d 5a 90 00'),
        string_hex('$hex2', '68 74 74 70 3a 2f 2f'),
        string_text('$s1', 'DropAndRun', 'wide ascii nocase'),
        string_text('$s2', 'cmd.exe /c', ''),
    ]
    condition_lines = [
        condition_all_of('$hex1', '$s1', '$s2'),
        condition_filesize('8', '512'),
        condition_pe_section('.text', '4096'),
    ]
    print(build_rule(header, meta_lines, string_lines, condition_lines))


if __name__ == '__main__':
    main()

