def quote(value):
    """Wrap an IMAP astring in double quotes, escaping backslashes and quotes."""
    body = value.replace('\\', '\\\\').replace('"', '\\"')
    return ''.join(['"', body, '"'])


def flag_list(flags):
    """Normalise a flag string into a parenthesised flag list."""
    inner = flags.strip().strip('()').strip()
    return ''.join(['(', inner, ')'])


def literal_size(size):
    """Render an octet count as an IMAP literal marker."""
    return ''.join(['{', str(size), '}'])


def login_cmd(tag, user, password):
    return ' '.join([tag, 'LOGIN', user, password])


def select_cmd(tag, mailbox):
    return ' '.join([tag, 'SELECT', mailbox])


def fetch_cmd(tag, seq, items):
    return ' '.join([tag, 'FETCH', seq, items])


def store_cmd(tag, seq, flag_op, flags):
    return ' '.join([tag, 'STORE', seq, flag_op, flag_list(flags)])


def copy_cmd(tag, seq, mailbox):
    return ' '.join([tag, 'COPY', seq, mailbox])


def search_cmd(tag, criteria):
    return ' '.join([tag, 'SEARCH', criteria])


def append_cmd(tag, mailbox, flags, date, size):
    return ' '.join([tag, 'APPEND', mailbox, flag_list(flags), quote(date),
                     literal_size(size)])


def uid_fetch_cmd(tag, seq, items):
    return ' '.join([tag, 'UID FETCH', seq, items])


def transcript_line(number, command):
    """Render one numbered client line of a session transcript."""
    return ''.join([str(number).rjust(3), ' C: ', command])


def main():
    session = [
        login_cmd('A01', 'user', 'pass123'),
        select_cmd('A02', 'INBOX'),
        fetch_cmd('A03', '1:5', '(FLAGS BODY.PEEK[])'),
        store_cmd('A04', '2', '+FLAGS', '(\\Seen \\Answered)'),
        copy_cmd('A05', '2:4', quote('Saved Mail')),
        search_cmd('A06', 'SINCE 1-Jan-2026 UNSEEN'),
        append_cmd('A07', 'INBOX', '(\\Draft)', '23-Sep-2026 10:04:00 +0200', 312),
        uid_fetch_cmd('A08', '4827:*', '(UID RFC822.SIZE)'),
    ]
    for number, command in enumerate(session, 1):
        print(transcript_line(number, command))


if __name__ == '__main__':
    main()

