def _check(*values):
    """Reject empty or padded arguments before they reach a CMake line."""
    for value in values:
        if not isinstance(value, str) or not value or value.strip() != value:
            raise ValueError(''.join(['invalid CMake argument: ', repr(value)]))


def cmake_min(version):
    _check(version)
    return ''.join(['cmake_minimum_required(VERSION ', version, ')'])


def proj_decl(name, version, langs):
    _check(name, version, langs)
    return ''.join(['project(', name, ' VERSION ', version, ' LANGUAGES ', langs, ')'])


def add_exec(name, src1, src2, src3):
    _check(name, src1, src2, src3)
    sources = ' '.join([src1, src2, src3])
    return ''.join(['add_executable(', name, ' ', sources, ')'])


def add_lib(name, lib_type, src1, src2):
    _check(name, lib_type, src1, src2)
    sources = ' '.join([src1, src2])
    return ''.join(['add_library(', name, ' ', lib_type, ' ', sources, ')'])


def target_link(name, scope, lib1, lib2):
    _check(name, scope, lib1, lib2)
    libs = ' '.join([lib1, lib2])
    return ''.join(['target_link_libraries(', name, ' ', scope, ' ', libs, ')'])


def target_inc(name, scope, dir1, dir2):
    _check(name, scope, dir1, dir2)
    dirs = ' '.join([dir1, dir2])
    return ''.join(['target_include_directories(', name, ' ', scope, ' ', dirs, ')'])


def set_prop(target, prop, val):
    _check(target, prop, val)
    return ''.join(['set_target_properties(', target, ' PROPERTIES ', prop, ' ', val, ')'])


def find_pkg(name, version, req):
    _check(name, version, req)
    return ''.join(['find_package(', name, ' ', version, ' ', req, ')'])


def build_script():
    """Assemble a complete CMakeLists body for the demo project."""
    return [
        cmake_min('3.16'),
        proj_decl('demo', '1.2.0', 'C CXX'),
        find_pkg('Threads', '1.0', 'REQUIRED'),
        add_lib('mylib', 'SHARED', 'a.c', 'b.c'),
        target_inc('mylib', 'PUBLIC', 'include', 'src'),
        add_exec('myapp', 'main.cpp', 'app.cpp', 'util.cpp'),
        target_link('myapp', 'PRIVATE', 'mylib', 'Threads::Threads'),
        set_prop('myapp', 'CXX_STANDARD', '17'),
    ]


def main():
    for line in build_script():
        print(line)


if __name__ == '__main__':
    main()

