"""Construction of BIP44 derivation paths for HD wallets."""

PURPOSE = "44'"

COIN_TYPES = {
    "bitcoin": "0",
    "ethereum": "60",
    "litecoin": "2",
    "dogecoin": "3",
    "ripple": "144",
    "cardano": "1815",
    "solana": "501",
}


def _hardened(value):
    return "".join([value, "'"])


def _validate(name, value):
    if not value.isdigit():
        raise ValueError("".join([name, " must be a decimal string, got ", repr(value)]))


def _path(coin_type, account, change, index):
    _validate("coin_type", coin_type)
    _validate("account", account)
    _validate("change", change)
    _validate("index", index)
    return "/".join(["m", PURPOSE, _hardened(coin_type), _hardened(account), change, index])


def path_bitcoin(account, change, index):
    return _path(COIN_TYPES["bitcoin"], account, change, index)


def path_ethereum(account, index):
    return _path(COIN_TYPES["ethereum"], account, "0", index)


def path_litecoin(account, change, index):
    return _path(COIN_TYPES["litecoin"], account, change, index)


def path_dogecoin(account, change, index):
    return _path(COIN_TYPES["dogecoin"], account, change, index)


def path_ripple(account, index):
    return _path(COIN_TYPES["ripple"], account, "0", index)


def path_cardano(account, change, index):
    return _path(COIN_TYPES["cardano"], account, change, index)


def path_solana(account, index):
    return _path(COIN_TYPES["solana"], account, "0", index)


def path_custom(coin_type, account, change, index):
    return _path(coin_type, account, change, index)


def describe(label, path):
    return " ".join([label.ljust(10), path])


def main():
    print(" ".join(["coin".ljust(10), "path"]))
    print(describe("bitcoin", path_bitcoin("0", "1", "5")))
    print(describe("ethereum", path_ethereum("0", "0")))
    print(describe("litecoin", path_litecoin("1", "0", "3")))
    print(describe("dogecoin", path_dogecoin("0", "0", "7")))
    print(describe("ripple", path_ripple("2", "1")))
    print(describe("cardano", path_cardano("0", "1", "0")))
    print(describe("solana", path_solana("3", "9")))
    print(describe("custom", path_custom("9000", "1", "1", "42")))


if __name__ == "__main__":
    main()

