def format_origin(warehouse, dock, bay):
    return '-'.join([warehouse, dock, bay])

def format_destination(receiver, city, region):
    return '|'.join([receiver, city, region])

def format_package(weight, unit, pkt_class):
    return ' '.join([weight, unit, pkt_class])

def format_routing(prefix, sequence, check_digit):
    return ' '.join([prefix, sequence, check_digit])

def validate_record(record):
    if len(record) != 12:
        raise ValueError('record must contain exactly twelve fields')
    for field in record:
        if not isinstance(field, str):
            raise TypeError('record fields must be strings')

def label(records):
    results = []
    for record in records:
        validate_record(record)

        warehouse, dock, bay = record[0], record[1], record[2]
        receiver, city, region = record[3], record[4], record[5]
        weight, unit, pkt_class = record[6], record[7], record[8]
        prefix, sequence, check_digit = record[9], record[10], record[11]

        origin_str = format_origin(warehouse, dock, bay)
        dest_str = format_destination(receiver, city, region)
        pkg_str = format_package(weight, unit, pkt_class)
        route_str = format_routing(prefix, sequence, check_digit)

        wh_prefix = '/'.join([warehouse, prefix])
        dock_seq = '/'.join([dock, sequence])
        bay_check = '/'.join([bay, check_digit])
        recv_weight = ':'.join([receiver, weight])

        results.append((
            origin_str,
            dest_str,
            pkg_str,
            route_str,
            wh_prefix,
            dock_seq,
            bay_check,
            recv_weight
        ))

    return results

if __name__ == '__main__':
    sample_records = [
        ('W1', 'D2', 'B3', 'CorpA', 'NY', 'NE', '15', 'kg', 'Haz', 'PRX', '123', '9'),
        ('W2', 'D1', 'B1', 'IncB', 'LA', 'SW', '2', 'lb', 'Std', 'PRY', '456', '2')
    ]
    for entry in label(sample_records):
        print(', '.join(entry))

FIELDS = (
    "course", "cuisine", "season",
    "prep_time", "cook_time", "rest_time",
    "flour", "sugar", "butter",
    "technique", "tool", "vessel",
)

LABELS = ("background", "timing", "ingredients", "method",
          "course/prep", "cuisine/cook", "season/rest", "flour/technique")


def format_background(course, cuisine, season):
    return ''.join([course, '-', cuisine, '-', season])


def format_timing(prep_time, cook_time, rest_time):
    return ''.join([prep_time, ':', cook_time, ':', rest_time])


def format_ingredients(flour, sugar, butter):
    return ''.join([flour, '/', sugar, '/', butter])


def format_method(technique, tool, vessel):
    return ''.join([technique, '-', tool, '-', vessel])


def validate(formula):
    if len(formula) != len(FIELDS):
        raise ValueError(''.join([
            "formula needs ", str(len(FIELDS)), " fields, got ", str(len(formula)),
        ]))
    for name, value in zip(FIELDS, formula):
        if not value.strip():
            raise ValueError(''.join(["field ", name, " is blank"]))


def recipe(formulas):
    results = []
    for formula in formulas:
        validate(formula)
        (course, cuisine, season, prep_time, cook_time, rest_time,
         flour, sugar, butter, technique, tool, vessel) = formula
        results.append((
            format_background(course, cuisine, season),
            format_timing(prep_time, cook_time, rest_time),
            format_ingredients(flour, sugar, butter),
            format_method(technique, tool, vessel),
            ''.join([course, ' ', prep_time]),
            ''.join([cuisine, ' ', cook_time]),
            ''.join([season, ' ', rest_time]),
            ''.join([flour, '+', technique]),
        ))
    return results


def report(rows):
    lines = []
    for index, row in enumerate(rows, start=1):
        lines.append(''.join(["formula ", str(index), ":"]))
        for label, value in zip(LABELS, row):
            lines.append(''.join(["  ", label, " = ", value]))
    return lines


def main():
    formulas = [
        ("a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l"),
        ("dessert", "french", "autumn", "15m", "40m", "10m",
         "rye", "cane", "salted", "folding", "whisk", "tart pan"),
    ]
    for line in report(recipe(formulas)):
        print(line)


if __name__ == "__main__":
    main()

