import sys


def is_leap_year(year):
    """Return True if `year` is a leap year in the proleptic Gregorian calendar."""
    if year % 4 != 0:
        return False
    if year % 100 != 0:
        return True
    return year % 400 == 0


def explain(year):
    """Build a human-readable chain of the divisibility rules for `year`."""
    parts = ['divisible by 4' if year % 4 == 0 else 'not divisible by 4']
    if year % 4 == 0:
        parts.append('divisible by 100' if year % 100 == 0 else 'not divisible by 100')
    if year % 100 == 0 and year % 4 == 0:
        parts.append('divisible by 400' if year % 400 == 0 else 'not divisible by 400')
    reasons = ', '.join(parts)
    verdict = 'leap' if is_leap_year(year) else 'common'
    return ''.join([str(year), ' is ', verdict, ': ', reasons])


def parse_years(tokens):
    """Turn command line tokens into ints, rejecting anything that is not a year."""
    years = []
    bad = []
    for token in tokens:
        try:
            years.append(int(token))
        except ValueError:
            bad.append(token)
    if bad:
        listed = ', '.join(bad)
        raise ValueError(''.join(['not valid years: ', listed]))
    return years


def leap_years_in(start, end):
    """List every leap year in the inclusive range [start, end]."""
    lo, hi = min(start, end), max(start, end)
    return [year for year in range(lo, hi + 1) if is_leap_year(year)]


def format_decade_row(decade):
    """Render one decade as its label plus a marker per year."""
    marks = ['*' if is_leap_year(decade + offset) else '.' for offset in range(10)]
    grid = ' '.join(marks)
    return ''.join([str(decade), 's ', grid])


def summarize_century(century_start):
    """Describe the leap years of a single century as a compact report."""
    leaps = leap_years_in(century_start, century_start + 99)
    rows = [format_decade_row(century_start + step) for step in range(0, 100, 10)]
    header = ''.join([
        'Century ', str(century_start), '-', str(century_start + 99),
        ' has ', str(len(leaps)), ' leap years',
    ])
    edges = ', '.join(str(year) for year in (leaps[0], leaps[-1]))
    footer = ''.join(['first/last: ', edges])
    return '\n'.join([header] + rows + [footer])


def main(argv):
    tokens = argv[1:]
    if not tokens:
        print(summarize_century(1900))
        return 0
    try:
        years = parse_years(tokens)
    except ValueError as error:
        print(''.join(['error: ', str(error)]), file=sys.stderr)
        return 1
    for year in years:
        print(explain(year))
    leaps = ', '.join(str(year) for year in years if is_leap_year(year))
    print(''.join(['leap years given: ', leaps or 'none']))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

