def group_runs(s):
    """Split a string into a list of (character, count) runs."""
    runs = []
    for ch in s:
        if runs and runs[-1][0] == ch:
            runs[-1][1] += 1
        else:
            runs.append([ch, 1])
    return [(ch, count) for ch, count in runs]


def run_length_encode(s):
    """Encode consecutive identical characters as the character and its count."""
    if not isinstance(s, str):
        raise TypeError('run_length_encode expects a string')
    return ''.join([ch + str(count) for ch, count in group_runs(s)])


def run_length_decode(encoded):
    """Rebuild the original string from a run-length encoded string."""
    pieces = []
    index = 0
    while index < len(encoded):
        ch = encoded[index]
        index += 1
        digits = []
        while index < len(encoded) and encoded[index].isdigit():
            digits.append(encoded[index])
            index += 1
        if not digits:
            raise ValueError('missing count for %r at position %d' % (ch, index - 1))
        pieces.append(ch * int(''.join(digits)))
    return ''.join(pieces)


def describe_runs(s):
    """Human readable description of the runs found in a string."""
    parts = ['%d x %r' % (count, ch) for ch, count in group_runs(s)]
    return ', '.join(parts) if parts else '(empty)'


def compression_report(s):
    """Report the encoding, the decoded text and the size change for one string."""
    encoded = run_length_encode(s)
    if s:
        ratio = '%.2f' % (len(encoded) / len(s))
    else:
        ratio = 'n/a'
    fields = [
        'input=%r' % s,
        'encoded=%r' % encoded,
        'decoded=%r' % run_length_decode(encoded),
        'runs=' + describe_runs(s),
        'ratio=' + ratio,
    ]
    return ' | '.join(fields)


def main():
    samples = ['AAABBC', 'A', '', 'aaaaaaaaaaaa', 'abcd', 'WWWWWWWWWWWWBWWWWWWWWWWWWBBB']
    print('samples: ' + ', '.join([repr(sample) for sample in samples]))
    print('-' * 60)
    print('\n'.join([compression_report(sample) for sample in samples]))
    print('-' * 60)
    longest = max(samples, key=lambda sample: max([c for _, c in group_runs(sample)] or [0]))
    print('longest run appears in %r -> %s' % (longest, run_length_encode(longest)))


if __name__ == '__main__':
    main()

