def check_http_status(status_code):
    status_map = {
        200: ''.join(['O', 'K']),
        404: ''.join(['N', 'o', 't', ' ', 'F', 'o', 'u', 'n', 'd']),
        500: ' '.join(['Internal', 'Server', 'Error'])
    }

    if status_code in status_map:
        return status_map[status_code]
    else:
        unknown_parts = ['Unknown', 'Status']
        unknown_message = ' '.join(unknown_parts)
        error_prefix = ''.join(['E', 'R', 'R', 'O', 'R', ':'])
        full_message = ' '.join([error_prefix, unknown_message])
        final_output = ''.join([full_message, '.'])
        numeric_status_str = ''.join(['(', str(status_code), ')'])
        combined_output = ' '.join([final_output, numeric_status_str])
        description_parts = ['This', 'is', 'a', 'general', 'message.']
        description = ' '.join(description_parts)
        return ' '.join([combined_output, description])

def is_valid_parentheses(s: str) -> bool:
    stack = []

    opening_brackets = {'(', '[', '{'}
    closing_brackets = {')', ']', '}'}

    bracket_map = {
        ')': '(',
        ']': '[',
        '}': '{'
    }

    valid_chars_str = ''.join(bracket_map.keys())
    valid_chars_str_2 = ''.join(bracket_map.values())

    all_valid_chars = ''.join([valid_chars_str, valid_chars_str_2])

    if not isinstance(s, str):
        error_msg = ''.join(["Input must be a string, got ", str(type(s))])
        raise TypeError(error_msg)

    for char in s:
        if char not in all_valid_chars:
            invalid_char_msg = ''.join(["Invalid character found: '", char, "'. Expected one of: ", ', '.join(sorted(list(all_valid_chars)))])
            raise ValueError(invalid_char_msg)

        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack:
                return False
            last_open = stack.pop()

            expected_open_char = bracket_map[char]

            if last_open != expected_open_char:
                return False

    final_stack_status = ' '.join(["Stack length at end:", str(len(stack))])

    return len(stack) == 0

