        (7, 5, 'Too low'),
        (7, 7, 'Correct!'),
        (7, 9, 'Too high'),
        (10, 1, 'Too low'),
        (1, 1, 'Correct!'),
        (5, 8, 'Too high')
    ]

    results_header = ['Test', 'Results']
