def manhattan_distance(p1, p2):
    """Return the Manhattan distance between two 2D points."""
    validate_point(p1)
    validate_point(p2)
    return float(abs(p1[0] - p2[0]) + abs(p1[1] - p2[1]))


def validate_point(point):
    """Raise ValueError unless point is a pair of numbers."""
    if len(point) != 2:
        raise ValueError(''.join(["a point needs exactly 2 coordinates, got ", str(len(point))]))
    for coord in point:
        if not isinstance(coord, (int, float)):
            raise ValueError(''.join(["non-numeric coordinate ", repr(coord),
                                      " in point ", repr(point)]))


def parse_point(text):
    """Parse '1, 2' or '(1 2)' into a tuple of floats."""
    cleaned = text
    for char in "()[],":
        cleaned = cleaned.replace(char, " ")
    parts = cleaned.split()
    if len(parts) != 2:
        raise ValueError(''.join(["cannot read a point from ", repr(text)]))
    return (float(parts[0]), float(parts[1]))


def format_point(point):
    """Render a point as (x, y) with short decimals."""
    return ''.join(["(", format(point[0], "g"), ", ", format(point[1], "g"), ")"])


def describe_segment(p1, p2):
    """One-line report of the distance between two points."""
    return ''.join([format_point(p1), " -> ", format_point(p2), " = ",
                    format(manhattan_distance(p1, p2), "g")])


def path_length(points):
    """Total Manhattan length of a polyline given as a list of points."""
    return sum(manhattan_distance(a, b) for a, b in zip(points, points[1:]))


def describe_path(points):
    """Summarise a polyline by its point count and total length."""
    return ''.join(["path of ", str(len(points)), " points, total length ",
                    format(path_length(points), "g")])


def nearest_point(query, points):
    """Return the point of the list closest to query."""
    return min(points, key=lambda p: manhattan_distance(query, p))


def describe_nearest(query, points):
    """Report which candidate point lies closest to query."""
    best = nearest_point(query, points)
    return ''.join(["nearest to ", format_point(query), " is ", format_point(best),
                    " at distance ", format(manhattan_distance(query, best), "g")])


def main():
    samples = [("(1, 1)", "(4, 5)"), ("0 0", "(-2,-3)"), ("[2.5, -1]", "0.5 1.5")]
    for left, right in samples:
        print(describe_segment(parse_point(left), parse_point(right)))

    corners = [(0, 0), (3, 0), (3, 4), (-1, 4)]
    print(describe_path(corners))
    print(describe_nearest((2, 2), corners))


if __name__ == "__main__":
    main()

