def count_char(text, char_to_count):
    """Count how many times char_to_count appears in text."""
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    if not isinstance(char_to_count, str):
        raise TypeError('char_to_count must be a string')
    if len(char_to_count) != 1:
        raise ValueError(''.join([
            'char_to_count must be exactly one character, got ',
            repr(char_to_count),
        ]))
    total = 0
    for character in text:
        if character == char_to_count:
            total += 1
    return total


def count_many(text, chars):
    """Return a list of (char, count) pairs, one per requested character."""
    return [(char, count_char(text, char)) for char in chars]


def describe_count(text, char):
    """Build a one-line human readable sentence for a single count."""
    total = count_char(text, char)
    return ''.join([repr(char), ' appears ', str(total), ' time(s) in ', repr(text)])


def bar_line(char, total):
    """Render one row of a simple histogram for a character count."""
    return ''.join([repr(char), ' | ', '#' * total, ' ', str(total)])


def most_common_char(text):
    """Return the character occurring most often, or None for empty text."""
    best = None
    best_count = 0
    for character in sorted(set(text)):
        total = count_char(text, character)
        if total > best_count:
            best = character
            best_count = total
    return best


