    """Short human description of the list handed to the generator."""
    if not lst:
        return 'the empty list'
    names = sorted({type(item).__name__ for item in lst})
    kinds = ', '.join(names)
    return ''.join(['a list of ', str(len(lst)), ' element(s) of type ', kinds])


