    """Build a full textual report for the permutations of lst."""
    perms = generate_permutations(lst)
    sections = [
        ''.join(['Input:  ', format_permutation(lst)]),
        ''.join(['Detail: ', describe_input(lst)]),
        ''.join(['Count:  ', str(len(perms))]),
