from datetime import date


def _validate(description, amount, date_str):
    problems = []
    if not isinstance(description, str) or not description.strip():
        problems.append('description must be a non-empty string')
    try:
        amount = float(amount)
    except (TypeError, ValueError):
        problems.append('amount must be a number')
    else:
        if amount < 0:
            problems.append('amount must not be negative')
    try:
        parts = date_str.split('-')
        date(int(parts[0]), int(parts[1]), int(parts[2]))
    except (AttributeError, IndexError, ValueError):
        problems.append('date must be in YYYY-MM-DD format')
    if problems:
        raise ValueError('; '.join(problems))
    return amount


def record_expense(expenses, description, amount, date_str):
    amount = _validate(description, amount, date_str)
    expenses.append({
        'description': description,
        'amount': amount,
        'date': date_str,
    })


def format_expense(expense):
    return ''.join([
        expense['date'],
        '  ',
        expense['description'].ljust(20),
        '{:>10.2f}'.format(expense['amount']),
    ])


def monthly_totals(expenses):
    totals = {}
    for expense in expenses:
        month = expense['date'][:7]
        totals[month] = totals.get(month, 0.0) + expense['amount']
    return totals


def format_report(expenses):
    lines = [''.join(['DATE'.ljust(12), 'DESCRIPTION'.ljust(20), 'AMOUNT'.rjust(10)])]
    for expense in sorted(expenses, key=lambda e: e['date']):
        lines.append(format_expense(expense))
    lines.append('-' * 42)
    summary = monthly_totals(expenses)
    for month in sorted(summary):
        lines.append(''.join([month, ' total: ', '{:.2f}'.format(summary[month])]))
    total = sum(expense['amount'] for expense in expenses)
    lines.append(''.join(['grand total: ', '{:.2f}'.format(total)]))
    return '\n'.join(lines)


def main():
    expenses = []
    record_expense(expenses, 'Rent', 1000.0, '2023-10-01')
    record_expense(expenses, 'Groceries', 50.0, '2023-10-25')
    record_expense(expenses, 'Dinner', 25.50, '2023-10-26')
    record_expense(expenses, 'Bus pass', 42.0, '2023-11-02')
    print(format_report(expenses))
    labels = ', '.join(expense['description'] for expense in expenses)
    print(''.join(['descriptions: ', labels]))
    months = ', '.join(sorted(monthly_totals(expenses)))
    print(''.join(['months covered: ', months]))


