def proper_divisors(num):
    """Return the sorted proper positive divisors of num."""
    if num < 1:
        raise ValueError("num must be a positive integer")
    divisors = {1} if num > 1 else set()
    step = 2
    while step * step <= num:
        if num % step == 0:
            divisors.add(step)
            partner = num // step
            if partner != num:
                divisors.add(partner)
        step += 1
    return sorted(divisors)


def is_perfect_number(num):
    """True when num equals the sum of its proper positive divisors."""
    return num > 1 and sum(proper_divisors(num)) == num


def divisor_sum_expression(divisors):
    """Render a divisor sum as an arithmetic expression."""
    if not divisors:
        return "0"
    return ' + '.join(str(d) for d in divisors)


def classify(num):
    """Label num as perfect, abundant or deficient."""
    total = sum(proper_divisors(num))
    if total == num:
        return "perfect"
    return "abundant" if total > num else "deficient"


