import sys


def format_ordinal(n):
    tens = n % 100
    if 11 <= tens <= 13:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return ''.join([str(n), suffix])


def describe(n, prime):
    return ''.join([format_ordinal(n), " prime is ", str(prime)])


def format_row(index_text, prime_text, width):
    return ''.join([index_text.rjust(width), " | ", prime_text])


def format_rule(width):
    return ''.join(["-" * width, "-+-", "-" * len("nth prime")])


def parse_index(text):
    stripped = text.strip()
    if not stripped.isdigit():
        raise ValueError(''.join(["not a positive integer: ", repr(text)]))
    value = int(stripped)
    if value < 1:
        raise ValueError(''.join(["index must be at least 1, got ", stripped]))
    return value


def _is_prime(candidate, known_primes):
    for prime in known_primes:
        if prime * prime > candidate:
            break
        if candidate % prime == 0:
            return False
    return True


def first_primes(count):
    if count < 1:
        raise ValueError("count must be at least 1")
    primes = [2]
    candidate = 3
    while len(primes) < count:
        if _is_prime(candidate, primes):
            primes.append(candidate)
        candidate += 2
    return primes


def nth_prime(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be a positive integer")
    if n < 1:
        raise ValueError("n must be a positive integer")
    return first_primes(n)[-1]


def main(argv):
    args = argv[1:] or ["1", "5", "10", "25", "100"]
    try:
        wanted = [parse_index(arg) for arg in args]
    except ValueError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    width = max([len("N")] + [len(str(value)) for value in wanted])
    print(format_row("N", "nth prime", width))
    print(format_rule(width))
    for value in wanted:
        print(format_row(str(value), str(nth_prime(value)), width))
    largest = max(wanted)
    print(describe(largest, nth_prime(largest)))
    return 0


if __name__ == "__main__":
