def calculate_gcd(a, b):
    """Return the greatest common divisor of two non-negative integers."""
    validate_operand('a', a)
    validate_operand('b', b)
    while b:
        a, b = b, a % b
    return a


def validate_operand(name, value):
    """Reject anything that is not a non-negative int."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(''.join([name, ' must be an int, got ', type(value).__name__]))
    if value < 0:
        raise ValueError(''.join([name, ' must be non-negative, got ', str(value)]))


def gcd_steps(a, b):
    """Return the division steps as (dividend, divisor, remainder) triples."""
    validate_operand('a', a)
    validate_operand('b', b)
    steps = []
    while b:
        steps.append((a, b, a % b))
        a, b = b, a % b
    return steps


def format_steps(a, b):
    """Return one explanation line per division, plus a closing result line."""
    lines = []
    for dividend, divisor, remainder in gcd_steps(a, b):
        quotient = dividend // divisor
        lines.append(''.join([
            str(dividend), ' = ', str(quotient), ' * ', str(divisor),
            ' + ', str(remainder),
        ]))
    lines.append(''.join(['gcd(', str(a), ', ', str(b), ') = ',
                          str(calculate_gcd(a, b))]))
    return lines


def coprime_report(pairs):
    """Describe, one line per pair, whether the two numbers share a factor."""
    lines = []
    for a, b in pairs:
        divisor = calculate_gcd(a, b)
        label = ''.join(['(', str(a), ', ', str(b), ')'])
        if divisor == 1:
            lines.append(''.join([label, ' is coprime']))
        else:
            lines.append(''.join([label, ' shares the factor ', str(divisor)]))
    return lines


def main():
    samples = [(48, 18), (17, 5), (270, 192), (14, 0)]
    for a, b in samples:
        for line in format_steps(a, b):
            print(line)
        print()
    for line in coprime_report(samples):
        print(line)
    try:
        calculate_gcd(-4, 12)
    except ValueError as exc:
        print(''.join(['rejected: ', str(exc)]))


if __name__ == '__main__':
    main()

