import random
import sys
from collections import Counter


def simulate_dice_rolls(n):
    """Roll a fair six-sided die n times and return the list of outcomes."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    return [random.randint(1, 6) for _ in range(n)]


def format_rolls(rolls, per_line=20):
    """Render the outcomes as comma separated lines of at most per_line values."""
    lines = []
    for start in range(0, len(rolls), per_line):
        chunk = rolls[start:start + per_line]
        lines.append(', '.join(str(value) for value in chunk))
    return '\n'.join(lines)


def tally(rolls):
    """Count how often each face from 1 to 6 appeared."""
    counts = Counter(rolls)
    return {face: counts.get(face, 0) for face in range(1, 7)}


def histogram(counts, width=40):
    """Build a text histogram, one line per die face."""
    total = sum(counts.values())
    busiest = max(counts.values()) if total else 0
    rows = []
    for face, count in sorted(counts.items()):
        bar_length = 0 if busiest == 0 else round(count * width / busiest)
        share = 0.0 if total == 0 else 100.0 * count / total
        rows.append('face {0} | {1:<{2}} {3:>5} ({4:5.1f}%)'.format(
            face, '#' * bar_length, width, count, share))
    return '\n'.join(rows)


def summarize(rolls):
    """Describe the average roll and which faces came up most often."""
    if not rolls:
        return 'no rolls performed'
    counts = tally(rolls)
    top = max(counts.values())
    leaders = [str(face) for face, count in counts.items() if count == top]
    parts = [
        'rolls: {0}'.format(len(rolls)),
        'mean: {0:.3f}'.format(sum(rolls) / len(rolls)),
        'most frequent: {0}'.format('/'.join(leaders)),
    ]
    return ' | '.join(parts)


def report(n, seed=None):
    """Simulate n rolls and return a printable multi-section report."""
    if seed is not None:
        random.seed(seed)
    rolls = simulate_dice_rolls(n)
    sections = [
        'Outcomes',
        format_rolls(rolls),
        '',
        'Distribution',
        histogram(tally(rolls)),
        '',
        summarize(rolls),
    ]
    return '\n'.join(sections)


def main(argv):
    n = int(argv[0]) if argv else 60
    seed = int(argv[1]) if len(argv) > 1 else None
    print(report(n, seed=seed))


if __name__ == '__main__':
    main(sys.argv[1:])

