def triangular_number(n: int) -> int:
    """Return the nth triangular number: 1 + 2 + ... + n."""
    if n < 0:
        raise ValueError("n must be non-negative")
    return n * (n + 1) // 2


def expansion(n: int) -> str:
    """Render the sum that defines the nth triangular number."""
    if n == 0:
        return "0"
    terms = [str(k) for k in range(1, n + 1)]
    if n > 6:
        terms = terms[:3] + ["...", terms[-1]]
    return ' + '.join(terms)


def describe(n: int) -> str:
    """One line stating both the expansion and the value for n."""
    return ''.join(["T(", str(n), ") = ", expansion(n), " = ", str(triangular_number(n))])


def triangular_sequence(count: int) -> list:
    """The first `count` triangular numbers, starting at n = 1."""
    return [triangular_number(n) for n in range(1, count + 1)]


def format_sequence(count: int) -> str:
    return ', '.join([str(t) for t in triangular_sequence(count)])


def format_row(n: int, width: int) -> str:
    value = str(triangular_number(n)).rjust(6)
    return ''.join([str(n).rjust(3), " | ", expansion(n).ljust(width), " | ", value])


def build_table(limit: int) -> str:
    width = max(len(expansion(n)) for n in range(1, limit + 1))
    header = ''.join(["  n | ", "sum".ljust(width), " |   T(n)"])
    rows = [format_row(n, width) for n in range(1, limit + 1)]
    return '\n'.join([header, '-' * len(header)] + rows)


def triangle_shape(n: int) -> str:
    """Draw n rows of stars; the total star count is the nth triangular number."""
    lines = []
    for row in range(1, n + 1):
        lines.append(''.join([' ' * (n - row), '* ' * row]))
    return '\n'.join(lines)


def parse_targets(text: str) -> list:
    """Read a comma or space separated list of indices."""
    tokens = text.replace(',', ' ').split()
    bad = [tok for tok in tokens if not tok.isdigit()]
    if bad:
        listing = ', '.join(bad)
        raise ValueError("not a non-negative integer: " + listing)
    return [int(tok) for tok in tokens]


def main() -> None:
    print(build_table(8))
    print()
    for n in parse_targets("1, 4 10, 100"):
        print(describe(n))
    print()
    print("first ten:", format_sequence(10))
    print()
    print(triangle_shape(5))


if __name__ == "__main__":
    main()

